/**
 * `gateforge tests mark` on an obligation a coverage disposition withheld:
 * the refusal names the disposition that excused it, not a generic
 * "not generated by the current policies".
 */
import { describe, expect, it } from 'vitest';
import { withTempRepo } from '@gate-forge/core';
import { configYml, installFixture, runCli } from './helpers.js';

const INVOICES_REASON = 'invoices are reconciled offline';

/** Top-level coverage block: one table excused as `other` with a reason. */
const COVERAGE_YML = `coveragePolicy:
  tables:
    - name: invoices
      requiredOperations: [read]
      disposition:
        kind: other
        reason: ${INVOICES_REASON}
`;

describe('gateforge tests mark: withheld obligations', () => {
  it('names the table, the disposition kind and reason, and the one-operation alternative', async () => {
    await withTempRepo({}, async (repo) => {
      installFixture(repo);
      repo.writeFiles({
        '.gateforge.yml': configYml({}) + COVERAGE_YML,
        'src/invoices.txt': 'invoices fixture.table\n',
        '.gateforge/adapters/invoices.mjs': 'export default {};\n',
      });
      const result = await runCli(repo, [
        'tests', 'mark', '--test', 'tests/invoices.spec.js', '--kind', 'browser-e2e',
        '--obligation', 'tenant.invoices:persistence:read', '--reason', 'owner note',
      ]);
      expect(result.code).not.toBe(0);
      expect(result.stderr).toContain("obligation 'tenant.invoices:persistence:read' is withheld by table 'tenant.invoices'");
      expect(result.stderr).toContain(`kind 'other'`);
      expect(result.stderr).toContain(INVOICES_REASON);
      expect(result.stderr).toContain('a classification-policy `disable: [<op>]` excuses one operation');
    });
  });

  it('keeps the generic message for an id no policy generates', async () => {
    await withTempRepo({}, async (repo) => {
      installFixture(repo);
      const result = await runCli(repo, [
        'tests', 'mark', '--test', 'tests/x.spec.js', '--kind', 'browser-e2e',
        '--obligation', 'nowhere:persistence:read', '--reason', 'owner note',
      ]);
      expect(result.code).not.toBe(0);
      expect(result.stderr).toContain("unknown obligation id 'nowhere:persistence:read'");
      expect(result.stderr).toContain('not generated by the current policies');
    });
  });
});
